using Tarnquill.Cli.Infrastructure;

namespace Tarnquill.Cli.Commands;

public static class BranchStartCommand
{
    public static int Run(string[] args)
    {
        var fetch = ProcessRunner.Run("git", "fetch", "origin", "main");
        return fetch.ExitCode == 0 ? 0 : 1;
    }
}
